    with open(path, 'rb') as f:
        raw = f.read()
    if raw[:2] == b'\x1f\x8b':
        raw = gzip.decompress(raw)
    return raw.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.splitlines() if l.strip() != '']


def local_to_epoch(naive, tz, fold=0):
    return int(naive.replace(tzinfo=tz, fold=fold).timestamp())


def ambiguous_epoch(naive, tz, dst):
    """dst True -> first occurrence (fold 0), False -> second."""
    return local_to_epoch(naive, tz, 0 if dst else 1)


