        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return int(d.timestamp())


def std_offset(tz, naive):
    d = naive.replace(tzinfo=tz)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_abbr(text, tz):
    out = []
    header = None
    for line in lines_of(text):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        d = datetime.strptime(r['Date'], '%m/%d/%Y')
        t = r['Time'].upper()
        if 'AM' in t or 'PM' in t:
            tm = datetime.strptime(t, '%I:%M:%S %p')
        else:
            tm = datetime.strptime(t, '%H:%M:%S')
        naive = d.replace(hour=tm.hour, minute=tm.minute, second=tm.second)
        zone = r.get('Zone', '').upper()
        ep = ambiguous_epoch(naive, tz, not zone.endswith('ST'))
        out.append((r['Record'], r['Badge'], r['Punch'].upper(), ep))
    return out


def parse_epoch(text):
    out = []
    schema = 1
    for line in lines_of(text):
        o = json.loads(line)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and len(o) == 1:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, dr, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
            ep = int(ms) // 1000
        else:
            pid, emp, dr = o['id'], o['emp'], o['dir']
            if 'ts_ms' in o and o['ts_ms'] is not None:
                ep = int(o['ts_ms']) // 1000
            else:
                ep = int(o['ts'])
        out.append((str(pid), emp, dr.upper(), ep))
    return out


def parse_offset(text):
    out = []
    rd = csv.DictReader(io.StringIO('\n'.join(lines_of(text))), delimiter=';')
    for r in rd:
        d = 'IN' if r['event'].strip() == 'clock_in' else 'OUT'
        out.append((r['punch_id'], r['employee'], d, parse_iso(r['timestamp'])))
    return out


def parse_legacy(text, tz):
    out = []
    default = None
    cur = None
    for line in lines_of(text):
        t = line[0]
        if t == 'H':
            off = line[13:18].strip()
            if len(off) == 5 and off[0] in '+-':
                s = 1 if off[0] == '+' else -1
                cur = s * (int(off[1:3]) * 3600 + int(off[3:5]) * 60)
            else:
                cur = None
        elif t == 'D':
            pid = line[1:9]
            badge = 'E' + line[9:15].strip()
            dr = 'IN' if line[15] == 'I' else 'OUT'
            naive = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
