        r = {k.strip(): (v or '').strip() for k, v in r.items()}
        naive = datetime.strptime(r['Datum'] + ' ' + r['Uhrzeit'], '%d.%m.%Y %H:%M')
        ep = ambiguous_epoch(naive, tz, r['Zeitzone'].upper() != 'MEZ')
        out.append((r['Nr'], r['Ausweis'], 'IN' if r['Buchung'] == 'K' else 'OUT', ep))
    return out


