            per.setdefault(emp, []).append((ep, 0 if dr == 'OUT' else 1, site, pid, dr))

    homezone = {e: sites[h][0] for e, h in home.items()}

    def rnd(ep, tz):
        off = int(datetime.fromtimestamp(ep, tz).utcoffset().total_seconds())
        loc = ep + off
        return (loc + 180) // 360 * 360 - off

