                    shifts.append((pend_in[0], r, pend_in[1]))
                    pend_in = None
                else:
                    if pend_in:
                        open_in(pend_in)
                        pend_in = None
                    if pstart <= workday(r, eid) <= pend:
                        exc['orphan_outs'] += 1
        if pend_in:
            open_in(pend_in)

