        for i, o, site in shifts:
            wd = workday(i, eid)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (o - i) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = sites[site][0]
            night = 0
            t = i
            while t < o:
                h = datetime.fromtimestamp(t, tz).hour
                if h >= 22 or h < 6:
                    night += 1
                t += 60
            night = min(night, paid)
            rows.append([i, wd, paid, night, 0])
        rows.sort(key=lambda x: x[0])
        daily = {}
        nondaily = []
        for row in rows:
            u = daily.get(row[1], 0)
            dot = max(0, u + row[2] - 480) - max(0, u - 480)
            daily[row[1]] = u + row[2]
            row[4] = dot
        weekly = {}
        for row in rows:
            wk = row[1] - timedelta(days=row[1].weekday())
            u = weekly.get(wk, 0)
            reg = row[2] - row[4]
            wot = max(0, u + reg - 2400) - max(0, u - 2400)
            weekly[wk] = u + reg
            row[4] += wot
        gross = Decimal(0)
        for i, wd, paid, night, ot in rows:
            rate = None
            for ef, rt in rates.get(eid, []):
                if ef <= wd:
                    rate = rt
            if rate is None:
                rate = Decimal(0)
            gross += rate * (Decimal(paid - ot) + Decimal('1.5') * ot) / 60 \
                + rate * Decimal('0.15') * night / 60
        gross = gross.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result[eid] = {
            'shifts': len(rows), 'paid_minutes': sum(r[2] for r in rows),
            'overtime_minutes': sum(r[4] for r in rows),
            'night_minutes': sum(r[3] for r in rows), 'gross': gross}

    tot = {k: sum(v[k] for v in result.values())
           for k in ('shifts', 'paid_minutes', 'overtime_minutes', 'night_minutes')}
    tot['gross'] = sum((v['gross'] for v in result.values()), Decimal(0))
    fmt = lambda d: '{:.2f}'.format(d)
    out = {
        'period': {'start': period['start'], 'end': period['end']},
        'employees': {k: dict(v, gross=fmt(v['gross'])) for k, v in result.items()},
        'exceptions': dict(exc, corrections_applied=applied),
        'totals': dict(tot, gross=fmt(tot['gross'])),
    }
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


def read_csv_text(text):
    return list(csv.DictReader(io.StringIO('\n'.join(lines_of(text)))))


